module.exports = {
  default: {
    paths: ['specs/**/*.feature'],
    require: ['features/support/**/*.js', 'features/step_definitions/**/*.js'],
    format: ['progress'],
    formatOptions: { snippetInterface: 'synchronous' }
  }
};

const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  async openApp() {
    const window = new Window({
      url: 'http://localhost',
      pretendToBeVisual: true
    });
    this.window = window;
    this.document = window.document;

    // Load the app HTML
    const fs = require('fs');
    const path = require('path');
    const htmlPath = path.resolve(__dirname, '../../index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    // Write HTML to the document
    this.document.open();
    this.document.write(html);
    this.document.close();

    // Wait for DOM to be ready
    await new Promise(resolve => setTimeout(resolve, 100));

    // Load the app script
    const scriptPath = path.resolve(__dirname, '../../js/app.js');
    const scriptContent = fs.readFileSync(scriptPath, 'utf8');
    const script = this.document.createElement('script');
    script.textContent = scriptContent;
    this.document.body.appendChild(script);

    // Wait for script to execute
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  async reloadApp() {
    // Save current localStorage
    const localStorageData = {};
    for (let i = 0; i < this.window.localStorage.length; i++) {
      const key = this.window.localStorage.key(i);
      localStorageData[key] = this.window.localStorage.getItem(key);
    }

    // Reopen the app
    await this.openApp();

    // Restore localStorage
    for (const [key, value] of Object.entries(localStorageData)) {
      this.window.localStorage.setItem(key, value);
    }

    // Trigger storage event
    this.window.dispatchEvent(new this.window.Event('storage'));

    // Wait for app to re-render
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  getTodoElements() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getActiveFilter() {
    const selected = this.document.querySelector('.filters .selected');
    return selected ? selected.textContent.trim() : null;
  }
}

setWorldConstructor(AppWorld);

const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the app has no todos', async function () {
  await this.openApp();
  const todos = this.getTodoElements();
  expect(todos).to.have.length(0);
});

Given('a todo titled {string} exists as active', async function (title) {
  await this.openApp();
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await new Promise(resolve => setTimeout(resolve, 50));

  // Verify todo was created
  const todos = this.getTodoElements();
  const todo = todos.find(t => t.querySelector('label').textContent === title);
  expect(todo, `Todo "${title}" not found`).to.exist;
  expect(todo.classList.contains('completed'), 'Todo should not be completed').to.be.false;
});

Given('a completed todo titled {string} exists', async function (title) {
  await this.openApp();
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await new Promise(resolve => setTimeout(resolve, 50));

  // Mark as completed
  const todos = this.getTodoElements();
  const todo = todos.find(t => t.querySelector('label').textContent === title);
  expect(todo, `Todo "${title}" not found`).to.exist;
  const checkbox = todo.querySelector('.toggle');
  checkbox.click();
  await new Promise(resolve => setTimeout(resolve, 50));

  // Verify it's completed
  expect(todo.classList.contains('completed'), 'Todo should be completed').to.be.true;
});

