/**
 * TodoMVC App - Vanilla JS Implementation
 * @planks("the app has no todos")
 * @planks("a todo titled {string} exists as active")
 * @planks("a completed todo titled {string} exists")
 * @planks("a todo titled {string} exists")
 * @planks("a todo titled {string} is being edited")
 * @planks("the user navigates to {string}")
 * @planks("the user types {string} in the new-todo input and presses Enter")
 * @planks("the user clicks the toggle checkbox on the {string} todo")
 * @planks("the user clicks the toggle-all checkbox")
 * @planks("the user clicks the Clear completed button")
 * @planks("the user double-clicks the {string} todo label")
 * @planks("the user changes the edit input to {string} and presses Enter")
 * @planks("the user changes the edit input to {string} and blurs the input")
 * @planks("the user changes the edit input to {string} and presses Escape")
 * @planks("the user clears the edit input and presses Enter")
 * @planks("the user clears the edit input and blurs the input")
 * @planks("the user clicks the destroy button on the {string} todo")
 * @planks("the page is reloaded")
 * @planks("a todo titled {string} appears in the todo list")
 * @planks("the new-todo input is empty")
 * @planks("the new-todo input has focus")
 * @planks("no todo is created")
 * @planks("the {string} todo is completed")
 * @planks("the {string} todo is active")
 * @planks("the {string} todo is removed")
 * @planks("the {string} todo remains")
 * @planks("the toggle-all checkbox is checked")
 * @planks("the toggle-all checkbox is not checked")
 * @planks("the Clear completed button is hidden")
 * @planks("the Clear completed button is visible")
 * @planks("the {string} todo is in editing mode")
 * @planks("the edit input contains {string}")
 * @planks("the edit input has focus")
 * @planks("the todo is titled {string}")
 * @planks("the todo is not in editing mode")
 * @planks("the counter shows {string}")
 * @planks("the main section is hidden")
 * @planks("the footer is hidden")
 * @planks("the main section is visible")
 * @planks("the footer is visible")
 * @planks("the {string} todo is visible")
 * @planks("the {string} todo is not visible")
 * @planks("the {string} filter is selected")
 */
(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var STORAGE_KEY = 'todos-vanillajs';

	var App = {
		todos: [],
		bindingEvents: false,

		init: function () {
			this.todos = this.loadTodos();
			this.cacheElements();
			this.bindEvents();
			this.render();
		},

		cacheElements: function () {
			this.newTodoInput = document.querySelector('.new-todo');
			this.todoList = document.querySelector('.todo-list');
			this.toggleAll = document.querySelector('#toggle-all');
			this.clearCompleted = document.querySelector('.clear-completed');
			this.todoCount = document.querySelector('.todo-count');
			this.mainSection = document.querySelector('.main');
			this.footer = document.querySelector('.footer');
			this.filters = document.querySelector('.filters');
		},

		bindEvents: function () {
			if (this.bindingEvents) return;
			this.bindingEvents = true;

			this.newTodoInput.addEventListener('keydown', this.handleNewTodoKeydown.bind(this));
			this.toggleAll.addEventListener('change', this.handleToggleAll.bind(this));
			this.clearCompleted.addEventListener('click', this.handleClearCompleted.bind(this));
			this.filters.addEventListener('click', this.handleFilterClick.bind(this));
			window.addEventListener('hashchange', this.handleRouteChange.bind(this));
		},

		handleNewTodoKeydown: function (e) {
			if (e.keyCode !== ENTER_KEY) return;

			var title = this.newTodoInput.value.trim();
			if (!title) {
				this.newTodoInput.value = '';
				return;
			}

			this.addTodo(title);
			this.newTodoInput.value = '';
		},

		addTodo: function (title) {
			this.todos.push({
				id: Date.now(),
				title: title,
				completed: false
			});
			this.saveTodos();
			this.render();
		},

		handleToggleAll: function () {
			var isChecked = this.toggleAll.checked;
			this.todos.forEach(function (todo) {
				todo.completed = isChecked;
			});
			this.saveTodos();
			this.render();
		},

		handleClearCompleted: function () {
			this.todos = this.todos.filter(function (todo) {
				return !todo.completed;
			});
			this.saveTodos();
			this.render();
		},

		handleFilterClick: function (e) {
			if (e.target.tagName === 'A') {
				window.location.hash = e.target.getAttribute('href');
			}
		},

		handleRouteChange: function () {
			this.render();
		},

		getFilteredTodos: function () {
			var route = window.location.hash || '#/';
			return this.todos.filter(function (todo) {
				if (route === '#/active') return !todo.completed;
				if (route === '#/completed') return todo.completed;
				return true;
			});
		},

		toggleTodo: function (id) {
			var todo = this.todos.find(function (t) { return t.id === id; });
			if (todo) {
				todo.completed = !todo.completed;
				this.saveTodos();
				this.render();
			}
		},

		deleteTodo: function (id) {
			this.todos = this.todos.filter(function (t) { return t.id !== id; });
			this.saveTodos();
			this.render();
		},

		editTodo: function (id, newTitle) {
			var trimmed = newTitle.trim();
			if (!trimmed) {
				this.deleteTodo(id);
				return;
			}
			var todo = this.todos.find(function (t) { return t.id === id; });
			if (todo) {
				todo.title = trimmed;
				this.saveTodos();
				this.render();
			}
		},

		saveTodos: function () {
			try {
				localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
			} catch (e) {
				// localStorage not available
			}
		},

		loadTodos: function () {
			try {
				var data = localStorage.getItem(STORAGE_KEY);
				return data ? JSON.parse(data) : [];
			} catch (e) {
				return [];
			}
		},

		render: function () {
			var filtered = this.getFilteredTodos();
			var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
			var completedCount = this.todos.filter(function (t) { return t.completed; }).length;

			// Render todo list
			this.todoList.innerHTML = filtered.map(function (todo) {
				var completedClass = todo.completed ? ' completed' : '';
				var checkedAttr = todo.completed ? ' checked' : '';
				return '<li data-id="' + todo.id + '" class="' + completedClass + '">' +
					'<div class="view">' +
					'<input class="toggle" type="checkbox"' + checkedAttr + '>' +
					'<label>' + this.escapeHtml(todo.title) + '</label>' +
					'<button class="destroy"></button>' +
					'</div>' +
					'<input class="edit" value="' + this.escapeHtml(todo.title) + '">' +
					'</li>';
			}.bind(this)).join('');

			// Bind todo events
			this.bindTodoEvents();

			// Update counter
			var itemText = activeCount === 1 ? 'item' : 'items';
			this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemText + ' left';

			// Show/hide main and footer
			if (this.todos.length === 0) {
				this.mainSection.style.display = 'none';
				this.footer.style.display = 'none';
			} else {
				this.mainSection.style.display = '';
				this.footer.style.display = '';
			}

			// Update toggle-all state
			this.toggleAll.checked = this.todos.length > 0 && activeCount === 0;

			// Update clear completed visibility
			this.clearCompleted.style.display = completedCount > 0 ? '' : 'none';

			// Update filter selection
			var route = window.location.hash || '#/';
			var filterLinks = this.filters.querySelectorAll('a');
			filterLinks.forEach(function (link) {
				var href = link.getAttribute('href');
				if (route === href || (route === '' && href === '#/')) {
					link.classList.add('selected');
				} else {
					link.classList.remove('selected');
				}
			});
		},

		bindTodoEvents: function () {
			var self = this;
			var todoItems = this.todoList.querySelectorAll('li');

			todoItems.forEach(function (li) {
				var id = parseInt(li.dataset.id, 10);
				var toggle = li.querySelector('.toggle');
				var destroy = li.querySelector('.destroy');
				var label = li.querySelector('label');
				var editInput = li.querySelector('.edit');

				toggle.addEventListener('change', function () {
					self.toggleTodo(id);
				});

				destroy.addEventListener('click', function () {
					self.deleteTodo(id);
				});

				label.addEventListener('dblclick', function () {
					li.classList.add('editing');
					editInput.focus();
				});

				editInput.addEventListener('keydown', function (e) {
					if (e.keyCode === ENTER_KEY) {
						editInput.blur();
					} else if (e.keyCode === ESCAPE_KEY) {
						editInput.value = li.querySelector('label').textContent;
						editInput.blur();
						li.classList.remove('editing');
					}
				});

				editInput.addEventListener('blur', function () {
					if (li.classList.contains('editing')) {
						self.editTodo(id, editInput.value);
					}
				});
			});
		},

		escapeHtml: function (str) {
			var div = document.createElement('div');
			div.textContent = str;
			return div.innerHTML;
		}
	};

	// Initialize app when DOM is ready
	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', function () { App.init(); });
	} else {
		App.init();
	}
})();

